import os
import re

DEFAULTS = {
    "PAYHOOK_API_TOKEN": None,
    "PAYHOOK_WEBHOOK_SECRET": None,
    "PAYHOOK_ENDPOINT": "https://api.payments.example/v1",
    "PAYHOOK_TIMEOUT": "10",
    "PAYHOOK_REGION": "eu",
}

# Values for these keys are never printed in full (for example by `doctor`).
SECRET_KEYS = {"PAYHOOK_API_TOKEN", "PAYHOOK_WEBHOOK_SECRET"}

_EXPORT_PREFIX = re.compile(r"^export\s+")


def _parse_dotenv_line(line):
    """Return (key, value) for an assignment line, or None to skip it."""
    line = line.strip()
    if not line or line.startswith("#"):
        return None
    line = _EXPORT_PREFIX.sub("", line, count=1)
    if "=" not in line:
        return None
    key, value = line.split("=", 1)
    key = key.strip()
    if not key:
        return None
    value = value.strip()
    # Strip one matching pair of surrounding quotes; the value inside is kept as-is.
    if len(value) >= 2 and value[0] == value[-1] and value[0] in ("'", '"'):
        value = value[1:-1]
    return key, value


def read_dotenv(path):
    values = {}
    if not os.path.exists(path):
        return values
    with open(path, encoding="utf-8") as handle:
        for line in handle:
            parsed = _parse_dotenv_line(line)
            if parsed is not None:
                key, value = parsed
                values[key] = value
    return values


def load_config(environ=None, dotenv_path=".env"):
    environ = os.environ if environ is None else environ
    dotenv = read_dotenv(dotenv_path)
    config = {}
    for key, default in DEFAULTS.items():
        if key in environ:
            config[key] = (environ[key], "env")
        elif key in dotenv:
            config[key] = (dotenv[key], ".env")
        else:
            config[key] = (default, "default")
    return config


def display_value(key, value):
    """Printable form of a setting value; secrets show only their length."""
    if value is None:
        return "<not set>"
    if key in SECRET_KEYS:
        return f"<redacted, {len(value)} chars>"
    return value

